CREATE TABLE records (id VARCHAR(36) PRIMARY KEY, kind VARCHAR(40) NOT NULL, revision INT NOT NULL, payload CLOB NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE INDEX records_kind ON records(kind);
CREATE TABLE revisions (id VARCHAR(36) NOT NULL, revision INT NOT NULL, payload CLOB NOT NULL, changed_at TIMESTAMP NOT NULL, PRIMARY KEY(id,revision));
CREATE TABLE audit (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor VARCHAR(150), action VARCHAR(200), subject VARCHAR(100), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE secrets (name VARCHAR(60) PRIMARY KEY, ciphertext CLOB NOT NULL);
